import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    
    static long[] p;
    static int n;
    
    static long f(int a, int b){
        int q = a + 2*b;
        int r = 3 * n - 2 * a - b;
        return 2 * p[a] + p[q] + 3 * p[r];
        
    }
	public static void main (String[] args) throws java.lang.Exception
	{
	Scanner sc = new Scanner(System.in);
	int t = sc.nextInt();
	while(t-->0)  {
	    n = sc.nextInt();
	    long[] x = new long[3*n];
	    for(int i=0; i<3*n; i++){
	        x[i] = sc.nextLong();
	    }
	    Arrays.sort(x);
	    long[] a = new long[3*n];
	    for(int i=0; i<3*n; i++){
	        a[i] = x[3*n-1-i];
	    }
	    
	    p = new long[3*n+1];
	    for(int i=0; i<3*n; i++){
	        p[i+1] = p[i] + a[i];
	    }
	    
	    long ans = 0;
	   
	   for(int A=0; A<=n; A++){
	       int lo = 0;
	       int hi = n - A;
	       while(lo<hi){
	           int mid = (lo+hi)/2;
	           
	           if(f(A,mid)<=f(A,mid+1)){
	               lo = mid + 1;
	           }else{
	               hi = mid;
	           }
	       }
	       ans = Math.max(ans,f(A,lo));
	   }
	   System.out.println(ans);
	}
	}
}
